={{
{
  "model": "deepseek-chat",
  "messages": [
    {
      "role": "system",
      "content": "Ты — ассистент для парсинга музыкальных заявок (Demo Drop).\n\nТВОЯ ЗАДАЧА — проанализировать входные данные, которые состоят из МЕТАДАННЫХ (от кого пришло письмо реально) и ТЕЛА ПИСЬМА.\n\nЛОГИКА РАБОТЫ:\n1. Сначала проверь ТЕЛО ПИСЬМА. Если это ПЕРЕСЛАННОЕ письмо (начинается с 'Fwd:', 'Пересылаемое сообщение', или содержит технический заголовок '... написал(а):'), то извлекай данные (Email, Имя) из текста этого заголовка.\n2. Если это ПРЯМОЕ письмо (нет признаков пересылки), бери 'email' и 'contact_name' из предоставленных полей METADATA_FROM.\n\nВЕРНИ JSON с такими полями:\n1. date: Дата получения письма. Формат: 'YYYY-MM-DD'. Если есть дата в тексте пересылки — бери её, иначе бери из METADATA_DATE.\n2. contact_name: Имя Фамилия автора. Если имя на латинице, транслитерируй/переведи на русский (Sergey -> Сергей). Если в метаданных только email, попробуй найти подпись в конце письма.\n3. artist_name: Название проекта/группы. Если не указано явно, дублируй имя.\n4. email: Реальный email автора. Для прямых писем бери из METADATA_FROM. Для пересланных — из тела письма.\n5. telegram: Юзернейм телеграм (через @), если есть в тексте.\n6. city: Город, если указан.\n7. music_links: Если в теме или тексте есть 'SourceAudio' — пиши строго 'SourceAudio'. ИНАЧЕ — ищи ссылки (Google Drive, Yandex Disk, SoundCloud).\n8. other_links: Ссылки на соцсети, сайт.\n9. references: Новое поле. Если автор пишет 'подойдет для проекта Х', 'в стиле сериала Y', 'референс к Z' — перечисли эти проекты/референсы через запятую. Если нет — ставь null.\n10. summary: Краткая суть письма (1-2 предложения, о чем музыка, жанр, цель).\n\nЕсли поле не найдено — null."
    },
    {
      "role": "user",
      "content": `METADATA_FROM: ${$json.headers?.from || $json.from || "Unknown"}
METADATA_SUBJECT: ${$json.headers?.subject || $json.subject || "Unknown"}
METADATA_DATE: ${$json.headers?.date || $json.date || "Unknown"}

BODY_TEXT:
${$json.text}`
    }
  ],
  "temperature": 0.1,
  "response_format": {
    "type": "json_object"
  }
}
}}

parameters.jsCode:
const content = $input.item.json.choices[0].message.content;
const cleanJson = content.replace(/```json/g, '').replace(/```/g, '').trim();
const parsed = JSON.parse(cleanJson);

// Логика обработки даты
if (parsed.date) {
  // DeepSeek возвращает ДД.ММ.ГГГГ (22.02.2026). Превращаем в YYYY-MM-DD
  const parts = parsed.date.split('.');
  if (parts.length === 3) {
    parsed.date = `${parts[2]}-${parts[1]}-${parts[0]}`;
  }
} else {
  // Если DeepSeek не нашел дату — ставим сегодняшнюю
  parsed.date = new Date().toISOString().split('T')[0];
}

return { json: parsed };

const data = $('Format Data1').item.json;
const originalEmail = $('Email Trigger (IMAP)1').item.json;

const email = data.email;

// No email extracted — skip sending
if (!email) {
  return [];
}

const name = data.contact_name || 'Музыкант';
const artist = data.artist_name;
const links = data.music_links;
const refs = data.references;

const subjectRaw = originalEmail.headers?.subject || originalEmail.subject || 'Ваша заявка';
const subject = 'Re: ' + subjectRaw.replace(/^Re:\s*/i, '');

// Personalized opening based on what was found
let personalized = (artist && artist !== data.contact_name)
  ? `Получили заявку от проекта <strong>${artist}</strong>.`
  : 'Получили вашу заявку.';

if (links) {
  personalized += ' Ссылки на музыку зафиксированы — обязательно послушаем.';
}

// Build list of clarifying questions based on missing fields
const questions = [];
if (!links) {
  questions.push('Пришлите ссылки на вашу музыку (SoundCloud, Google Drive, Яндекс Диск и т.п.)');
}
if (!refs) {
  questions.push('Какие проекты или форматы вас интересуют? (фильмы, сериалы, реклама, игры — конкретные или любые?)');
}
questions.push('Каков статус прав на вашу музыку? (эксклюзив / неэксклюзив, есть ли издатель или лейбл?)');
questions.push('Что приоритетнее: синхронизация в конкретных проектах или плейлисты / медиапродвижение?');

const qHtml = questions.map(q => `  <li>${q}</li>`).join('\n');
const qText = questions.map((q, i) => `${i + 1}. ${q}`).join('\n');

const html = `<p>Привет, ${name}!</p>

<p>Спасибо за письмо — мы его получили. ${personalized}</p>

<p>Чтобы рассмотреть заявку эффективнее, уточните, пожалуйста:</p>
<ul>
${qHtml}
</ul>

<p>Постараемся ответить в ближайшее время.</p>

<hr style="border:none;border-top:1px solid #eee;margin:24px 0">

<p style="font-size:13px;color:#555">
  Подписывайтесь на нас:<br>
  <a href="https://www.instagram.com/sync_lab_music_agency/">Instagram</a> &nbsp;|&nbsp;
  <a href="https://t.me/synclab">Telegram</a>
</p>

<p style="font-size:13px;color:#555">
  Наша книга <em>«Музыкальный продюсер в кино»</em> доступна на
  <a href="https://eksmo.ru/book/muzykalnyy-prodyuser-v-kino-u-n--ITD1380619/">сайте ЭКСМО</a>.
</p>

<p style="font-size:11px;color:#aaa">Synclab Pro &nbsp;·&nbsp; sync@synclab.pro</p>`;

const text = `Привет, ${name}!\n\nСпасибо за письмо — мы его получили. ${personalized.replace(/<[^>]+>/g, '')}\n\nЧтобы рассмотреть заявку эффективнее, уточните:\n${qText}\n\nПостараемся ответить в ближайшее время.\n\n---\nInstagram: https://www.instagram.com/sync_lab_music_agency/\nTelegram: https://t.me/synclab\nКнига «Музыкальный продюсер в кино»: https://eksmo.ru/book/muzykalnyy-prodyuser-v-kino-u-n--ITD1380619/\n\nSynclab Pro`;

return {
  json: {
    to: email,
    subject: subject,
    html: html,
    text: text
  }
};
